//! Complete sorted ID expectations from independent CLR4.0 and CLR4.7.2 hosts.
//! Inputs below are generated synthetic keys. Expected permutations are encoded
//! as signed ID deltas (zigzag/LEB128), then base64; no native runtime is needed.
//! The reference comparison used the Microsoft native-style descending-Y
//! comparer and all 271 cases, including backing capacity and heap fallback.
use super::{legacy_sort, legacy_sort_depth, modern_sort, modern_sort_depth};
use std::cmp::Ordering;

fn decode(text: &str) -> Vec<usize> {
    let mut bits = 0u32;
    let mut bit_count = 0;
    let mut value = 0u32;
    let mut shift = 0;
    let mut previous = 0i64;
    let mut result = Vec::new();
    for byte in text.bytes().take_while(|&byte| byte != b'=') {
        let digit = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => panic!("invalid fixture base64"),
        };
        bits = (bits << 6) | u32::from(digit);
        bit_count += 6;
        if bit_count >= 8 {
            bit_count -= 8;
            let decoded = ((bits >> bit_count) & 255) as u8;
            bits &= (1 << bit_count) - 1;
            value |= u32::from(decoded & 127) << shift;
            if decoded & 128 == 0 {
                let delta = i64::from(value >> 1) ^ -i64::from(value & 1);
                previous += delta;
                result.push(usize::try_from(previous).unwrap());
                value = 0;
                shift = 0;
            } else {
                shift += 7;
                assert!(shift <= 28);
            }
        }
    }
    assert_eq!(shift, 0);
    result
}
#[derive(Clone)]
struct Case {
    keys: Vec<i64>,
    capacity: usize,
    depth_zero: bool,
}
fn cases() -> Vec<Case> {
    let mut cases = Vec::new();
    for n in [
        0usize, 1, 2, 3, 4, 15, 16, 17, 31, 32, 33, 63, 64, 127, 128, 257, 512, 1024,
    ] {
        for pattern in 0..6 {
            let keys: Vec<_> = (0..n)
                .map(|i| match pattern {
                    0 => 7,
                    1 => (i / 3) as i64,
                    2 => -(((i + 2) / 3) as i64),
                    3 => (i % 2) as i64,
                    4 => ((i * 37) % 13) as i64,
                    _ => (i.abs_diff(n / 2) % 7) as i64,
                })
                .collect();
            for depth_zero in [false, true] {
                cases.push(Case {
                    keys: keys.clone(),
                    capacity: n,
                    depth_zero,
                });
            }
        }
    }
    cases.push(Case {
        keys: (0..10000)
            .map(|i| ((i * 1103515245usize + 12345) % 17) as i64)
            .collect(),
        capacity: 10000,
        depth_zero: false,
    });
    for n in [17usize, 31, 127, 257, 1024, 4096] {
        for capacity in [n, 2 * n, 4 * n + 1] {
            for pattern in 0..3 {
                cases.push(Case {
                    keys: (0..n)
                        .map(|i| match pattern {
                            0 => 7,
                            1 => ((i * 37) % 11) as i64,
                            _ => (i.min(n - i) % 17) as i64,
                        })
                        .collect(),
                    capacity,
                    depth_zero: false,
                });
            }
        }
    }
    assert_eq!(cases.len(), 271);
    cases
}
#[test]
fn complete_legacy_clr40_id_permutations() {
    check(false, LEGACY);
}
#[test]
fn complete_modern_clr472_id_permutations() {
    check(true, MODERN);
}
fn check(modern: bool, expected: &[&str]) {
    assert_eq!(expected.len(), 271);
    for (case_index, (case, encoded)) in cases().into_iter().zip(expected).enumerate() {
        let mut values: Vec<_> = case.keys.into_iter().enumerate().collect();
        let mut compare = |a: &(usize, i64), b: &(usize, i64)| {
            let delta = b.1 - a.1;
            if delta > 0 {
                Ordering::Greater
            } else if delta < 0 {
                Ordering::Less
            } else {
                Ordering::Equal
            }
        };
        match (modern, case.depth_zero) {
            (false, false) => legacy_sort(&mut values, &mut compare),
            (false, true) => legacy_sort_depth(&mut values, &mut compare, 0),
            (true, false) => modern_sort(&mut values, case.capacity, &mut compare),
            (true, true) => modern_sort_depth(&mut values, &mut compare, 0),
        }
        assert_eq!(
            values.iter().map(|v| v.0).collect::<Vec<_>>(),
            decode(encoded),
            "case {case_index}"
        );
    }
}

